goal.statement:
let P := (i : Fin n) → T i;
let grid := {q | ∀ (i : Fin n), q i ∈ Q i};
let upper := {x | ∃ q ∈ grid, q ≤ x};
let cell := fun y => {x | x ∈ upper ∧ ∀ (i : Fin n), IsGreatest {a | a ∈ Q i ∧ a ≤ x i} (y i)};
(∀ ⦃x y y' : P⦄, x ∈ cell y → y' ∈ grid → y ≤ y' → y' ⊔ x ∈ cell y' ∧ ∃ x' ∈ cell y', x ≤ x') ∧
  ∀ y ∈ grid, IsSublattice (cell y)

